import logging
import time
from abc import ABCMeta, abstractmethod
from telnetlib import Telnet
from typing import Union

from taf.internal.robot_typecasts import time_to_seconds

from ..exceptions import BadPortNumber, BadResponse, PduConnectionError, Timeout
from .base import PDU


class TelnetPdu(PDU, metaclass=ABCMeta):
    """Class that makes it possible to
    manage a single PDU device over the telnet."""

    def __init__(self, host: str, port: int, timeout: Union[float, int]) -> None:
        super().__init__(host)
        self._port = port
        self._timeout = time_to_seconds(timeout)
        self._encoding = "utf-8"

    @property
    @abstractmethod
    def _max_ports(self):
        pass

    @abstractmethod
    def _build_telnet_command(self, port, status):
        """Build command for Telnet-based PDU get/set status"""

    @abstractmethod
    def _parse_response(self, response):
        """Parser for response from PDU"""

    def _set_port_status(self, port, status):
        logging.info(f"Telnet: Setting port to {status}: {port}")
        command = self._build_telnet_command(port, status=status)
        self._send_cmd(command)

    def get_port_status(self, port):
        logging.info(f"Telnet: Fetching status of port: {port}")
        command = self._build_telnet_command(port, status=None)
        response = self._execute_cmd(command)
        parsed_response = self._parse_response(response)
        return self._reversed_port_settings[parsed_response]

    def _connect(self):
        log_msg = f"Connecting to PDU under {self._host}:{self._port}"
        logging.info(log_msg)
        try:
            telnet_con = Telnet(self._host, self._port, self._timeout)
            return telnet_con
        except IOError as e:
            exc_msg = f"Cannot connect to PDU host={self._host}:{self._port})"
            logging.error(str(e))
            raise PduConnectionError(exc_msg)

    def _send_cmd(self, telnet_msg):
        telnet_con = self._connect()
        self._write_cmd(telnet_con, telnet_msg)

    def _write_cmd(self, telnet_con, telnet_msg):
        telnet_con.write(telnet_msg)
        telnet_con.close()

    def _execute_cmd(self, telnet_msg):
        start = time.time()
        telnet_con = self._connect()
        telnet_con.write(telnet_msg)
        return self._collect_output(telnet_con, start)

    def _collect_output(self, telnet_con, start):
        try:
            while time.time() - start < self._timeout:
                response = telnet_con.read_very_eager()
                if response != "":
                    return response
            raise Timeout("Telnet connection timed out.")
        except EOFError:
            raise BadResponse("No data available")
        finally:
            telnet_con.close()

    def _verify_port_number(self, port):
        if port not in range(1, self._max_ports + 1):
            exc_msg = f"Port number is invalid: {port}"
            raise BadPortNumber(exc_msg)
